<?php
require __DIR__.'/bootstrap.php';require_once __DIR__.'/../approval_workflow.php';$account=requireApprover($conn);$approverId=(int)$account['approver_id'];
$id=filter_var($_GET['id']??'',FILTER_VALIDATE_INT);if(!$id){http_response_code(404);exit('Request not found.');}
function reviewRecord($conn,$id,$account){return wfRow($conn,'SELECT r.* FROM borrowing_approvals r JOIN department_approvers d ON d.department_id=r.department_id WHERE r.approval_id=? AND r.approver_id=? AND d.is_active=1 AND d.approval_email=?','iis',[$id,(int)$account['approver_id'],$account['email']]);}
$r=reviewRecord($conn,$id,$account);if(!$r){http_response_code(404);exit('Request not found.');}
$error='';$notice=$_SESSION['approval_notice']??'';unset($_SESSION['approval_notice']);
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{approverCsrf();$_SESSION['approval_notice']=wfApproverDecision($conn,$id,$approverId,(string)($_POST['decision']??''),(string)($_POST['note']??''));header('Location: review.php?id='.$id);exit;}
 catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(Throwable $e){error_log('Department decision: '.$e->getMessage());$error='Unable to complete approval. Your request has not been signed. Please try again later.';}
 $r=reviewRecord($conn,$id,$account);
}
$s=json_decode($r['snapshot_json'],true);$asset=wfRow($conn,"SELECT asset_id FROM approver_assets WHERE approver_id=? AND asset_kind='combined'",'i',[$approverId]);
approverHeader('Review Request');
?>
<a href="approvals.php">← My Approvals</a><div class="heading"><div><p class="eyebrow">ROUND <?=(int)$r['round_no']?></p><h1>Request #<?=(int)$r['borrow_id']?></h1></div><span class="pill"><?=approverEscape(ucfirst($r['state']))?></span></div>
<?php if($notice):?><p role="status" class="success"><?=approverEscape($notice)?></p><?php endif;?><?php if($error):?><p role="alert" class="error"><?=approverEscape($error)?></p><?php endif;?>
<section class="panel"><h2><?=approverEscape($s['nama'])?></h2><p class="muted"><?=approverEscape($s['no_id_staf'].' · '.$s['unit_bahagian'])?></p><p><strong>Purpose:</strong> <?=approverEscape($s['tujuan_tempahan'])?><br><strong>Location:</strong> <?=approverEscape($s['lokasi_penggunaan'])?><br><strong>Borrowing period:</strong> <?=approverEscape($s['start_date'].' → '.$s['end_date'])?><br><strong>Contact:</strong> <?=approverEscape($s['no_tel'])?></p></section>
<section class="panel"><h2>Items confirmed by JTM</h2><p class="muted small"><?=approverEscape($r['confirmed_name'].' / '.$r['confirmed_at'])?></p><table><thead><tr><th>Item / accessories</th><th>Asset tag</th><th>Serial</th><th>Qty</th></tr></thead><tbody><?php foreach($s['equipment'] as $i):?><tr><td><?=approverEscape($i['name'])?><br><span class="muted"><?=approverEscape($i['description'])?></span></td><td><?=approverEscape($i['tagging_no'])?></td><td><?=approverEscape($i['serial_no'])?></td><td><?=(int)$i['quantity']?></td></tr><?php endforeach;?></tbody></table><p class="muted">JTM remarks: <?=approverEscape($r['jtm_note']?:'None')?></p></section>
<?php if($r['state']==='pending'):?><section class="panel"><h2>Your signature &amp; chop</h2><?php if($asset):?><div class="preview"><img alt="Your saved signature and chop" src="image.php?id=<?=(int)$asset['asset_id']?>"></div><p class="muted small">Approve &amp; Sign applies this image to the fixed department-lead box in the PDF.</p><?php else:?><p class="error">Upload your combined image before approving. <a href="signatures.php">My Signature &amp; Chop</a></p><?php endif;?>
<form method="post"><input type="hidden" name="csrf" value="<?=approverEscape($_SESSION['asset_csrf'])?>"><label for="note">Comments / rejection reason</label><textarea id="note" name="note" rows="3" maxlength="1000"></textarea><div class="decision-actions"><button name="decision" value="approve" <?=!$asset?'disabled':''?> onclick="return confirm('Approve this request and apply your saved signature and chop to its PDF?')">Approve &amp; Sign</button><button name="decision" value="reject" class="danger" onclick="return confirm('Reject this request? Enter the reason above first.')">Reject</button></div></form></section>
<?php else:?><section class="panel"><h2>Decision record</h2><p><?=approverEscape($r['lead_name'])?><br><?=approverEscape($r['decision_at']??'Selection changed before decision')?></p><?php if($r['decision_note']):?><p class="muted"><?=approverEscape($r['decision_note'])?></p><?php endif;?><?php if($r['pdf_filename']):?><a class="button" href="pdf.php?approval=<?=$id?>&amp;portal=approver" target="_blank" rel="noopener">View Approval PDF</a><?php if($r['state']==='superseded'):?><p class="muted small">This approval was superseded. Its PDF is retained as a historical record and does not authorize current handover.</p><?php endif;?><?php endif;?></section><?php endif;?>
<?php if($r): $events=wfAll($conn,'SELECT * FROM borrowing_approval_events WHERE approval_id=? ORDER BY event_id','i',[(int)$r['approval_id']]); ?><section class="panel"><h2>Approval audit trail</h2><table><thead><tr><th>Time</th><th>Action</th><th>By</th><th>Remarks</th></tr></thead><tbody><?php foreach($events as $event):?><tr><td><?=approverEscape($event['occurred_at'])?></td><td><?=approverEscape(str_replace('_',' ',$event['action']))?></td><td><?=approverEscape($event['actor_role'])?></td><td><?=approverEscape($event['detail'])?></td></tr><?php endforeach;?></tbody></table></section><?php endif;?>
